const item = $input.item.json;
const now = new Date();
const apptDate = item.APPOINTMENT_DATE ? new Date(item.APPOINTMENT_DATE) : null;
if (!apptDate) return null;
const hoursUntilAppt = (apptDate.getTime() - now.getTime()) / (1000 * 60 * 60);
item.hours_until = hoursUntilAppt;
item.needs_24h_reminder = hoursUntilAppt >= 23 && hoursUntilAppt <= 25 && item.REMINDER_SENT === 'FALSE' && item.STATUS === 'CONFIRMED';
item.appointment_display = apptDate.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
item.appointment_time_display = apptDate.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
return $input.item;
